    """
    One manifest format for every package kind (plugin, skill, app, companion, integration, model, wakeword, voice, theme, module). See platform plan 5.1 and .github's docs/PACKAGES.md.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    id: constr(pattern=r'^[a-z0-9][a-z0-9_-]{0,63}$') = Field(
        ...,
        description='Unique in the catalog. No third-party name in it. Not one of the nine reserved settings area ids (the static legacy routes under /settings).',
    )
    version: constr(pattern=r'^[0-9]+\.[0-9]+\.[0-9]+$')
    kind: Literal[
        'plugin',
        'skill',
        'app',
        'companion',
        'integration',
        'model',
        'wakeword',
        'voice',
        'theme',
        'module',
        'reference',
        'project',
    ] = Field(
        ...,
        description="A `plugin` is a self-contained, permissioned, installable capability (its own network access, its own recipe.json). A `skill` is plain instructions (a SKILL.md body, Claude-format-compatible) - no permissions, no recipe, composed into the chat model's system prompt when relevant, never runs on its own. See home/docs/dev.md's 'Naming: skill, plugin, command, connector' entry. A `reference` is a declarative offline knowledge archive (no code, like `model` and `voice`) - a Kiwix-style book a household installs and sizes before download; see `knowledge_source` below and home/docs/plans/knowledge-sources-2026-09-24.md. A `project` package declares a background project type: its body is `plan.json` (a `ProjectPlan`, this same file's own sibling `project.schema.json`'s `$defs/ProjectPlan`), never `recipe.json`.",
    )
    category: Literal[
        'Home',
        'Family',
        'Info',
        'Fun',
        'Media',
        'Robot body',
        'Health',
        'Learning',
        'Utilities',
    ]
    display: constr(min_length=1, max_length=60)
    description: constr(min_length=1, max_length=200)
    tool_label: constr(min_length=1, max_length=120) | None = Field(
        None,
        description="Optional (TOOL-EVENTS-01): the human label the turn stream's `tool_call` event carries while a package runs. Read from the manifest's own entry, so the label is the package's, not the route's. When it contains a `{place}` (or other `{arg}`) slot, the engine fills it from the call's `args` when that arg is present, else omits the slot entirely. Absent: the timeline falls back to the package's `display` name.",
    )
    offer: Offer | None = Field(
        None,
        description="TOOL-OFFER-01: whether this package tool may be offered to an adult written chat model. Home derives the live set from installed, enabled, smoke-healthy packages and the selected model's max_tools; absent means not measured and therefore not offered. `base` is part of the measured base set, `conditional` requires a declared gate and benchmark row, and `off` requires a reason.",
    )
    author: constr(min_length=1)
    license: constr(min_length=1)
    homepage: AnyUrl | None = None
    routing: Routing | None = None
    companion: Companion | None = Field(
        None,
        description='Required when kind is "companion" (session-a-intelligence.md step 8), unused otherwise. Composed by home/backend/src/lib/persona.ts into the turn engine\'s identity line and system-prompt fragment: display_name replaces the hardcoded "MaiPai" in "You are {display_name}, ...", the four style dials are the same ones lib/persona.ts already had before companions were packages, and examples is a short few-shot block (legacy\'s own finding: "the single biggest lever for small-model voice fidelity").',
    )
    knowledge_source: KnowledgeSource | None = Field(
        None,
        description='Required when kind is "reference" (an offline archive), and for a live plugin package that is one of the household\'s knowledge sources for `lookup()`\'s federation (home/docs/plans/knowledge-sources-2026-09-24.md, "Routing: one lookup, not one tool per source" - the resident model chooses badly between one tool per source, home#150, dev.md PHRASE-02 and DOC-TOOL-01, so every source is reached behind the one search tool instead); unused otherwise. Declares what this source is and, for an archive, every size a person could install, so Home\'s sizing wizard ("proposed, never fixed": it measures the chosen drive\'s free space and the hardware tier, recommends a flavour and bundle, and shows the size impact) reads `flavours[].approx_bytes` straight from the manifest, never a live network call.',
    )
    args: Any | None = Field(
        None, description="A JSON Schema for this package's call arguments."
    )
    incognito: Literal['blocked', 'ephemeral', 'unaffected'] = Field(
        ...,
        description='INCOGNITO-04: this package\'s behavior while Incognito is on. Required, never defaulted - a manifest that omits it fails validation the same way a manifest missing any other required field does, enforced by the one shared reader every route/install check calls (loadManifestOnly()/loadPackage(), lib/plugins.ts). "blocked": unavailable while Incognito is on (sharing, CHANNELS-01, anything that publishes for the family). "ephemeral": works normally, nothing it writes persists past the session (chat, a generation app\'s own generated-content tab). "unaffected": no personal data touched, nothing to gate.',
    )
    requires: list[str] | None = Field(
        None,
        description='Capabilities from the capability vocabulary (spec/vocab/capabilities.json) this package cannot run without.',
    )
    optional: list[str] | None = Field(
        None, description='Capabilities that add behavior but are not required.'
    )
    returns_blocks: (
        list[
            Literal[
                'spec_sheet',
                'data_table',
                'chart',
                'timeline',
                'todo_list',
                'image_gallery',
                'schedule_card',
                'comparison',
                'weather_card',
                'story_feed',
                'article',
                'media_card',
                'confirmation',
                'countdown',
            ]
        ]
        | None
    ) = Field(
        None,
        description='GENUI-01: the answer-block kinds this package may return on `PluginResult.blocks`, so the host and the store card know what it can emit. Optional; absent means none. The host drops a returned block whose kind is not listed.',
    )
    platforms: list[Literal['home', 'bot', 'web']] = Field(..., min_length=1)
    min_role: Literal['owner', 'admin', 'adult', 'teen', 'child', 'guest'] = Field(
        ..., description='The floor role a person needs to invoke this package.'
    )
    consequential: bool = Field(
        ...,
        description="Raises the routing bar (4.5): a consequential plugin needs more confidence before it fires - the model must propose it, gated on the household's own confirmation, never a deterministic auto-fire. A consequential package must never also declare `routing.patterns`: turnEngine.ts's route() only enforces the raised bar on the fuzzy/Tier 2 path, so a literal pattern match would fire it immediately, bypassing confirmation entirely (a real gap found and fixed, session-d-packages-and-store.md step 9 - route() itself now also refuses to treat a consequential manifest's own patterns as live, so a manifest bug here can no longer be the only thing standing between a security domain and skipping confirmation, but the manifest still shouldn't declare one).",
    )
    offline: Literal['full', 'degraded', 'unavailable'] = Field(
        ..., description='Stated offline behavior, required at bronze.'
    )
    config: list[settings_key_schema.SettingsKey] | None = None
    data_sources: list[privacy_row_schema.PrivacyRow] | None = Field(
        None,
        description="Feeds the generated privacy row (docs/ENGINEERING.md > Privacy). The shape is @maipai/standards' PrivacyRow, imported by $ref (std-v0.3.2).",
    )
    needs: list[Need] | None = Field(
        None, description='The capabilities this package needs for health derivation.'
    )
    permissions: list[str] | None = Field(
        None,
        description='From the fixed permissions enum (spec/vocab/permissions.json).',
    )
    notifications: list[Notification] | None = Field(
        None,
        description="Notification types this package declares, per docs/NOTIFICATIONS.md - registered into home/backend/src/lib/notificationTypes.ts's shared registry at load (registerPackageNotificationTypes()).",
    )
    cache: Cache | None = Field(
        None,
        description="How lib/packageCache.ts (session-d-packages-and-store.md step 3) keys and bounds this package's own cache. `additionalProperties: true` on purpose: a package's `host.fetch` call sites decide their own extra per-entry hints (4.10), this just fixes the ones the cache mechanism itself reads.",
    )
    warm: Warm | None = Field(
        None,
        description="A scheduled job that pre-populates this package's cache before anyone asks, so a common answer (the household's own weather) never waits on a live fetch.",
    )
    warm_on: list[constr(min_length=1)] | None = Field(
        None,
        description='Setting keys (spec/settings/keys.json ids) whose change should trigger an immediate warm outside `warm.schedule` - e.g. `household.home` changing re-warms `weather` right away instead of waiting for the next scheduled tick.',
    )
    backup: Literal['hot', 'cold', 'exclude'] | None = None
    background: bool = False
    contributes: Contributes | None = Field(
        None,
        description="Shell blueprints (6.1), keyed by blueprint kind: nav entries, pages, right-pane panels, settings sections, commands, quick actions, player hooks, admin sections. `additionalProperties: true` since most of 6.1's own blueprint kinds have no bundled package using them yet (Wave 1's `contributes: []` was a placeholder no package had populated); `widgets` and `pages` below are the two sub-fields session-d-packages-and-store.md steps 2/10 fix a real shape for. `pages` replaces a redundant top-level `pages: string[]` field (Session E flagged it 2026-09-06 as incompatible with this object shape and confirmed nothing in backend/src or frontend/src read it) - a package declaring a page uses `contributes.pages[]` now, never a second, competing field.",
    )
    setup: dict[str, Any] | None = Field(
        None,
        description='A declared setup flow, the one escape hatch beyond a plain settings form (docs/SETTINGS.md rule 1).',
    )
    provides: list[str] | None = Field(
        None,
        description='For integrations: what this package makes available to others (5.4).',
    )
    min_app: constr(pattern=r'^[0-9]+\.[0-9]+\.[0-9]+$') = Field(
        ..., description='Minimum hub/robot version this package needs.'
    )
    kit_version: str | None = Field(
        None,
        description="The @maipai/ui ui-v tag this package's UI was built against, if it ships one.",
    )
    reply: dict[str, Any] | None = Field(
        None, description='Default reply shape hints for the router, if any.'
    )
    timeout_ms: conint(ge=1) | None = Field(
        None,
        description='Bounds handle(). Defaults per 4.9: 4000 on the robot, 8000 on the hub.',
    )
    fallback_reply: FallbackReply | None = Field(
        None,
        description="A Tier 1 package's own answer when its Deno process crashes or times out (session-d-packages-and-store.md step 5) - required practically, not just structurally, for a Tier 1 package to clear bronze, since a crash with nothing to say is a dead end for whoever asked.",
    )
    tier: Literal[0, 1] = Field(
        ..., description='0: declarative (a recipe or prompt body). 1: Deno code.'
    )
    smoke: Smoke | None = Field(
        None,
        description='The smoke test entry, run at install, update, and on a schedule (lib/smoke.ts). `kind: "static"` (loads only), `"recipe_fixture"` + `fixture` (a Tier 0 plugin\'s own recipe run against a fixture-seeded HostEmulator), or `"deno_test"` (Tier 1, session-d step 5).',
    )
    exposes: Exposes | None = Field(
        None,
        description="wave-2.md's C-to-D contract: typed read queries a package offers beyond its own recipe, for C's Tier 2 tool-calling router to call directly rather than routing a whole turn through this package's `handle`.",
    )
    quality_scale: Literal['bronze', 'silver', 'gold'] | None = None
    channel: Literal['stable', 'beta'] = Field(
        'stable',
        description="The release channel this manifest version was published under (session-d step 6's store). A household's own per-package channel *choice* is store-side state, not this field - this is the publisher's declaration of what the version itself is.",
    )
    content_sha256: constr(pattern=r'^[a-f0-9]{64}$') | None = None
    signature: str | None = None
    signer: str | None = None
    source: Source | None = Field(
        None, description='For a package that graduated to its own repo (5.1).'
    )
